exercises.solution:
sealed class Reponse {}

class Succes extends Reponse {
  Succes(this.valeur);

  final int valeur;
}

class Echec extends Reponse {
  Echec(this.message);

  final String message;
}

String decrire(Reponse reponse) => switch (reponse) {
  Succes(:final valeur) => 'Valeur : $valeur',
  Echec(:final message) => 'Erreur : $message',
};

void main() {
  print(decrire(Succes(42)));
  print(decrire(Echec('Délai dépassé')));
}
